import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import type { z } from "zod";
import {
  AdminList, AuditPage, Attention, DisputePage, Funding, IncidentPage, LiveSnapshot, PaymentPage, PayoutPage, RiderPage, TrialBalance, TripDetail, TripPage,
} from "@/lib/schemas";

/**
 * The fixtures are generated by the backend's own tests from its real responses, and the backend fails if its responses
 * stop matching them. Parsing them here closes the loop: a change to the API that this panel cannot read fails a test
 * on whichever side moved.
 */
const cases: [string, z.ZodType][] = [
  ["admin-list.json", AdminList],
  ["audit-page.json", AuditPage],
  ["attention.json", Attention],
  ["dispute-page.json", DisputePage],
  ["funding.json", Funding],
  ["incident-page.json", IncidentPage],
  ["live-snapshot.json", LiveSnapshot],
  ["payment-page.json", PaymentPage],
  ["payout-page.json", PayoutPage],
  ["rider-page.json", RiderPage],
  ["trial-balance.json", TrialBalance],
  ["trip-detail.json", TripDetail],
  ["trip-page.json", TripPage],
];

describe("API contract fixtures", () => {
  it.each(cases)("%s parses with the panel's schema", (file, schema) => {
    const raw = JSON.parse(readFileSync(path.join(__dirname, "..", "fixtures", file), "utf8"));
    const result = schema.safeParse(raw);
    expect(result.success, result.success ? "" : JSON.stringify(result.error.issues.slice(0, 3))).toBe(true);
  });

  it("rejects a response that drifted (a renamed field)", () => {
    const raw = JSON.parse(readFileSync(path.join(__dirname, "..", "fixtures", "trip-page.json"), "utf8"));
    delete raw.items[0].customerName;
    expect(TripPage.safeParse(raw).success).toBe(false);
  });
});
